def transform(grid):
    from collections import Counter

    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find the horizontal repeat period of the patterned region.
    period = None
    for p in range(2, 10):
        matches = total = 0
        for r in range(3, h):
            for c in range(3, w - p):
                a, b = grid[r][c], grid[r][c + p]
                if a != 0 and b != 0:
                    total += 1
                    matches += (a == b)
        if total >= 20 and matches / total >= 0.94:
            period = p
            break

    if period is None:
        best = (-1, 0, None)
        for p in range(2, 10):
            matches = total = 0
            for r in range(3, h):
                for c in range(3, w - p):
                    a, b = grid[r][c], grid[r][c + p]
                    if a != 0 and b != 0:
                        total += 1
                        matches += (a == b)
            if total >= 20 and matches / total > best[0]:
                best = (matches / total, total, p)
        period = best[2] or 5

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                counts = Counter(
                    grid[r][x]
                    for x in range(3, w)
                    if x % period == c % period and grid[r][x] != 0
                )
                if counts:
                    out[r][c] = counts.most_common(1)[0][0]

    return out
